appearances.css:
.app{gap:4px;font-size:8px}
.top{gap:2px 3px}
.top button,.bars button{font-size:8px;padding:2px 5px;letter-spacing:.04em;min-width:0;border-radius:2px}
.rack{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:4px}
.mod{padding:3px 4px 4px;gap:2px 0;border-radius:2px;display:grid;grid-template-columns:repeat(var(--n,3),minmax(0,1fr));align-content:start}
.mod>h3,.mod>.seqhead,.mod>.bars,.mod>.seq,.mod>.pads,.mod>.top{grid-column:1/-1}
.mod h3{font-size:8px;letter-spacing:.12em;line-height:1.1;padding-bottom:2px;margin:0}
.mod h3 label{font-size:8px;gap:2px}
.mod:nth-child(1){--n:3;grid-column:span 3}
.mod:nth-child(2){--n:2;grid-column:span 2}
.mod:nth-child(3){--n:3;grid-column:span 3}
.mod:nth-child(4){--n:3;grid-column:span 3}
.mod:nth-child(5){--n:3;grid-column:span 3}
.mod:nth-child(7){--n:2;grid-column:span 2;order:6}
.mod:nth-child(6){--n:3;grid-column:span 3;order:7}
.mod:nth-child(8){--n:5;grid-column:span 5;order:8}
.mod.wide{--n:1;grid-column:1/-1;order:9}
.k,.k[style]{display:grid!important;grid-template-columns:minmax(0,1fr)!important;justify-items:center;align-items:start;align-content:start;gap:0;min-width:0}
.k label{order:3;font-size:7.5px;letter-spacing:-.04em;text-align:center;max-width:100%;line-height:1.1;white-space:normal;overflow:visible;text-overflow:clip;text-transform:none}
.k output{order:2;font-size:8px;text-align:center;line-height:1.1;color:var(--d-muted);white-space:nowrap}
.k .kn{order:1;width:26px!important;height:26px!important;justify-self:center!important}
.k .kn svg{width:100%;height:100%}
.k select{order:1;width:100%;font-size:7.5px;padding:3px 0;text-align:center;text-align-last:center;appearance:none;-webkit-appearance:none;border-radius:2px;cursor:pointer}
.k:has(select) label{order:2}
.mod:nth-child(6) .k:has(select){grid-column:span 2}
.pads{gap:2px}
.pads button{padding:4px 0;font-size:8px;letter-spacing:0;border-radius:2px;min-width:0}
.seqhead{display:flex!important;gap:0 10px;align-items:flex-start}
.seqhead .k{width:52px;flex:0 0 52px}
.seqhead .k:has(select){width:96px;flex:0 0 96px}
.bars{gap:2px}
.bars button{min-width:18px;padding:1px 4px}
.seq{overflow:hidden}
table{min-width:0;border-spacing:1px 1px}
th{width:22px;font-size:7.5px;padding-right:2px;line-height:1}
.st{height:9px}
.mod.wide>.top{margin-top:2px}
